"list\_patient\_medical\_records": {   
<sup>"signature":</sup> <sup>{</sup><sub>"parameters":</sub> [],   
"return": "dict"   
cu = self.current\_user   
if not cu or not cu.get('authenticated') or cu.get('role') != 'patient':   
return {'success': False, 'error': 'Access denied'}   
patient\_id = cu.get('patient\_id')   
if patient\_id not in self.patients:   
return {'success': False, 'error': 'Patient does not exist'}   
patient\_info = self.patients[patient\_id]   
if patient\_info.get('account\_status') != 'active':   
return {'success': False, 'error': 'Patient account is not active'}   
records = [mr for mr in self.medical\_records.values()   
if mr['patient\_id'] == patient\_id]   
return {'success': True, 'data': records}"   
